// Tilt Maze: tilt the whole maze with the arrows, d-pad or stick, and roll the marble into the
// hole with the flag. The other holes send you back to the start.
// Shows: map_set_angle on a map you collide with. mgetw(m, x, y, z, r) works on the rotated map,
// so the marble's physics is just gravity plus one push-out per contact; mtow() finds where a
// spot on the tilted maze is in the world (for the flag).
// map 0 = the maze; its origin is the middle of the floor's top, so it tilts about its center.
// tiles: 1 floor, 2 wall, 3 floor by the goal. vox 0 = the flag. sounds: 0 bump, 1 lost, 2 win, 3 start

const R = 0.28                     // marble radius
const START = [1.5, 1.5]           // where the marble starts (x, z) in the maze's own grid
const GOAL = [9, 9]                // the hole with the flag
const MAXTILT = 0.035              // turns, about 12.6 degrees
let bx, by, bz, vx, vy, vz         // marble position and velocity, in world space
let tp = 0, tr = 0                 // the maze's pitch and roll
let state = 'title', ticks = 0, best = null, flash = 0

function _init() {
  bg(1)
  let d = load()
  if (d) best = d.best
  reset()
}

// the marble back at the start, the maze level
function reset() {
  tp = tr = 0
  map_set_angle(0, [0, 0, 0])
  ;[bx, by, bz] = mtow(0, START[0], 1 + R + 0.05, START[1])   // the floor's top is y = 1 in the maze's grid
  vx = vy = vz = 0
}

function _update() {
  if (state != 'play') {
    if (btnp(4) || btnp(5)) {
      if (state != 'title') reset()
      state = 'play'; ticks = 0; sfx(3)
    }
    if (state == 'title') return
  }
  if (state == 'play') ticks++
  if (flash > 0) flash--

  // tilt toward the stick. The camera looks along +z, so screen right is -x:
  // pushing right raises the +x side (positive roll) and the marble rolls right;
  // pushing up lowers the far (+z) side (negative pitch) and the marble rolls away.
  let [sx, sy] = state == 'play' ? stick(0) : [0, 0]
  tp += (sy * MAXTILT - tp) * 0.08
  tr += (sx * MAXTILT - tr) * 0.08
  map_set_angle(0, [tp, 0, tr])

  // two small physics steps per update keep the marble from tunneling through walls
  for (let step = 0; step < 2; step++) {
    vy -= 0.005
    bx += vx; by += vy; bz += vz
    for (let pass = 0; pass < 3; pass++) {
      let [t, xi, yi, zi, nx, ny, nz, d] = mgetw(0, bx, by, bz, R)
      if (!t) break
      bx += nx * d; by += ny * d; bz += nz * d
      let vn = vx * nx + vy * ny + vz * nz          // speed into the surface
      if (vn < 0) {
        if (vn < -0.04 && abs(ny) < 0.5) sfx(0)     // a hard knock against a wall
        vx -= nx * vn * 1.3; vy -= ny * vn * 1.3; vz -= nz * vn * 1.3   // stop, with a small bounce
      }
    }
    vx *= 0.995; vz *= 0.995
  }

  // below the floor? mgetw also tells us which cell of the maze a point is in
  if (state == 'won') { if (by < -12) vx = vy = vz = 0; return }   // dropping out of sight
  let [t, xi, yi, zi] = mgetw(0, bx, by, bz)
  if (yi < 0) {
    if (xi == GOAL[0] && zi == GOAL[1]) {
      state = 'won'; sfx(2)
      let secs = ticks / 60
      if (best == null || secs < best) { best = secs; save({ best: best }) }
    } else { flash = 15; sfx(1); reset() }
  }
}

function fmt(s) { return flr(s * 10) / 10 + 's' }

function _draw() {
  cam_set_pos([0, 9, -6.2])
  cam_set_lookat([0, -0.6, 0.7])
  cam_set_fov(0.21)

  outline(0)
  if (flash > 0) for (let i = 0; i < 32; i++) pal(i, 8)
  map(0)
  pal()
  // the flag stands in the goal hole, like a golf flag: mtow() says where that spot of the maze's
  // grid is in the world right now, however the maze is tilted
  vox(0, ...mtow(0, GOAL[0] + 0.5, 1, GOAL[1] + 0.5), tp, 0, tr, 1.5)
  sphere(bx, by, bz, R, 7)

  print('Time ' + fmt(ticks / 60), 4, 4, 7, 0)
  if (best != null) { let b = 'Best ' + fmt(best); print(b, 252 - b.length * 7, 4, 10, 0) }
  if (state == 'title') {
    rectfill(28, 80, 227, 170, 1); rect(28, 80, 227, 170, 7)
    print('TILT MAZE', 65, 88, 10, 0, 2)
    print('Tilt with the arrows or stick', 26 + 6, 116, 7)
    print('Get the marble to the flag', 37, 128, 7)
    print('Other holes: back to start', 37, 140, 6)
    if (time() % 1 < 0.6) print('press O or X', 86, 156, 11)
  }
  if (state == 'won') {
    rectfill(40, 100, 215, 150, 1); rect(40, 100, 215, 150, 7)
    let m = best == ticks / 60 ? 'New best time!' : 'Best ' + fmt(best)
    print('You made it! ' + fmt(ticks / 60), 128 - (13 + fmt(ticks / 60).length) * 3.5, 108, 10, 0)
    print(m, 128 - m.length * 3.5, 122, 7, 0)
    print('O to play again', 75, 136, 6)
  }
}
